/**
 * Seven-Level Soroban Learning System — Level Definitions
 *
 * Each level is a sequence of phases:
 *   'observe'   – read-only lesson step (no bead interaction required)
 *   'guided'    – student moves beads to match a target (set-digit / set-number)
 *   'arithmetic'– guided arithmetic problem from the engine
 *   'challenge' – show-a-number challenge (student sets soroban to match)
 *   'complete'  – end-of-level summary (handled by LevelScreen)
 *
 * Existing lesson steps from sorobanLearningSteps.ts are referenced by id.
 * Arithmetic problems are generated by arithmeticEngine.ts at runtime.
 */

export type PhaseType =
  | 'observe'
  | 'guided'
  | 'arithmetic-add'
  | 'arithmetic-sub'
  | 'arithmetic-mixed'
  | 'challenge'
  | 'free-explore';

export interface LevelPhase {
  type: PhaseType;
  /** For observe/guided: reference to SOROBAN_BASICS_STEPS id */
  lessonStepId?: number;
  /** For challenge: max number to challenge with */
  challengeMax?: number;
  /** For challenge / arithmetic: how many questions */
  questionCount?: number;
  /** For challenge: how many correct to pass */
  passScore?: number;
  /**
   * Countdown timer in seconds for the entire play phase.
   * Undefined = no timer (observe/guided/free-explore phases).
   * Timer starts when the first interactive question begins.
   */
  timeLimitSeconds?: number;
  /** Short Tamil label shown in phase indicator */
  labelTa: string;
  /** Short English label shown in phase indicator */
  labelEn: string;
}

export interface LevelDefinition {
  id: number;           // 1-based
  emoji: string;
  titleEn: string;
  titleTa: string;
  descriptionEn: string;
  descriptionTa: string;
  color: string;        // CSS hex for level accent
  phases: LevelPhase[];
  /** Minimum score (0–100) to mark level complete. Observe-only = 0. */
  passThreshold: number;
}

